using Microsoft.Web.WebView2.Core; using System; using System.Windows; namespace AfAi; public partial class MainWindow : Window { public MainWindow(){ InitializeComponent(); Loaded += async (_, _) => { try { await Browser.EnsureCoreWebView2Async(); Browser.CoreWebView2.Settings.AreDevToolsEnabled=false; Browser.CoreWebView2.Settings.IsStatusBarEnabled=false; Browser.CoreWebView2.Settings.AreDefaultContextMenusEnabled=true; Browser.CoreWebView2.Settings.IsZoomControlEnabled=true; Browser.CoreWebView2.NavigationCompleted += (_, _) => LoadingPanel.Visibility=Visibility.Collapsed; Browser.CoreWebView2.Navigate("https://Fizer.ir"); } catch(Exception ex) { LoadingPanel.Child=new System.Windows.Controls.TextBlock { Text="برای اجرای اف Ai، Microsoft Edge WebView2 Runtime لازم است.\n"+ex.Message, Foreground=System.Windows.Media.Brushes.White, FontSize=16, TextWrapping=System.Windows.TextWrapping.Wrap, Margin=new Thickness(40), VerticalAlignment=VerticalAlignment.Center, HorizontalAlignment=HorizontalAlignment.Center }; } }; } }